# New approach: find all row pairs with shared columns containing 2s
def find_shared_columns(grid):
    h, w = len(grid), len(grid[0])
    shared = {}  # (r1, r2) -> sorted list of shared cols
    for r1 in range(h):
        for r2 in range(r1 + 2, h):  # need at least one row between them
            cols_r1 = set(c for c in range(w) if grid[r1][c] == 2)
            cols_r2 = set(c for c in range(w) if grid[r2][c] == 2)
            if cols_r1 & cols_r2:  # has intersection
                shared[(r1, r2)] = sorted(cols_r1 & cols_r2)
    return shared

shared_cols = find_shared_columns(demo_in)
print(f"Shared columns between row pairs:")
for (r1, r2), cols in shared_cols.items():
    print(f"  Row {r1} <-> Row {r2}: {cols}")

# Now build rectangles from shared columns
def fill_rectangles_new(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find all valid rectangles (pairs of rows with >= 2 shared columns)
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            shared = [c for c in range(w) if grid[r1][c] == 2 and grid[r2][c] == 2]
            if len(shared) < 2:
                continue  # need at least 2 columns for a proper rectangle

            c1, c2 = min(shared), max(shared)
            # Fill interior
            for r in range(r1 + 1, r2):
                for c in range(c1 + 1, c2):
                    if result[r][c] == 0:
                        result[r][c] = 1

    return result

