# Let me try the SIMPLEST possible rule: 
# A 0 becomes 1 if it's strictly between 2s in its row OR strictly between 2s in its column

def fill_simple(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        # Find all columns where grid[r][c] == 2
        cols_with_2s = [c for c in range(w) if grid[r][c] == 2]
        if len(cols_with_2s) >= 2:
            # Fill between first and last
            first, last = min(cols_with_2s), max(cols_with_2s)
            for c in range(first + 1, last):
                if result[r][c] == 0:
                    result[r][c] = 1

    for c in range(w):
        # Find all rows where grid[r][c] == 2
        rows_with_2s = [r for r in range(h) if grid[r][c] == 2]
        if len(rows_with_2s) >= 2:
            first, last = min(rows_with_2s), max(rows_with_2s)
            for r in range(first + 1, last):
                if result[r][c] == 0:
                    result[r][c] = 1

    return result

