def find_rectangles_no_2_inside(grid):
    h, w = len(grid), len(grid[0])
    rects = []
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != 2: continue
            for c2 in range(c1 + 2, w):
                for r2 in range(r1 + 2, h):
                    if grid[r1][c2] == 2 and grid[r2][c1] == 2 and grid[r2][c2] == 2:
                        # Check interior - must NOT contain any 2s
